var int VersusGroundProbeSerial;
// Native HP2 mount states advance on the dedicated server only while the
// owning pawn is temporarily presented as a simulated proxy.
var bool bVersusMountNetActive;
var bool bVersusMountAwaitResume;
var bool bVersusMountLocalHold;
var bool bVersusMountReleasePending;
var bool bVersusMountReleaseApplied;
var int VersusMountSerial;
var int VersusMountLocalSerial;
var float VersusMountStartTime;
var float VersusMountHoldStamp;
var float VersusMountNextReleaseTime;
var float VersusMountPredictedAt;
var vector VersusMountOriginalPivot;
var float VersusMountOriginalRadius;
var float VersusMountOriginalHeight;
var float VersusMountOriginalWidth;
var vector VersusMountReleaseLocation;
var rotator VersusMountReleaseRotation;
var Actor VersusMountReleaseBase;
var EPhysics VersusMountReleasePhysics;
var float VersusMountReleaseRadius;
var float VersusMountReleaseHeight;
var float VersusMountReleaseWidth;
var vector VersusMountReleasePivot;
var float VersusMountReleaseStamp;

function bool IsVersusMountState()
{
    return IsInState('Mounting') || IsInState('MountFinish');
}

simulated function ClearVersusMountPrediction()
{
    local SavedMove M;

    while (SavedMoves != None)
    {
        M = SavedMoves;
        SavedMoves = M.NextMove;
        M.Clear();
        M.NextMove = FreeMoves;
        FreeMoves = M;
    }
    if (PendingMove != None)
    {
        PendingMove.Clear();
        PendingMove.NextMove = FreeMoves;
        FreeMoves = PendingMove;
        PendingMove = None;
    }
    bUpdatePosition = False;
}

event Mount(vector Delta)
{
    if (bVersusDead || bVersusModeMovementLocked)
        return;

    if (Role == ROLE_Authority && Level.NetMode == NM_DedicatedServer
        && Player != None && RemoteRole == ROLE_AutonomousProxy)
    {
        VersusMountSerial++;
        VersusMountStartTime = Level.TimeSeconds;
        VersusMountHoldStamp = CurrentTimeStamp;
        VersusMountOriginalRadius = CollisionRadius;
        VersusMountOriginalHeight = CollisionHeight;
        VersusMountOriginalWidth = CollisionWidth;
        VersusMountOriginalPivot = PrePivot;
        bVersusMountNetActive = True;
        bVersusMountAwaitResume = False;
        ClientVersusMountBegin(VersusMountSerial);
        Super.Mount(Delta);
        // The stock latent Mounting label and MountFinish.PlayerTick now run
        // on authority; the owner and observers receive its actor animation.
        RemoteRole = ROLE_SimulatedProxy;
        Log("HPVersusMount phase=Begin serial=" $ VersusMountSerial
            $ " pawn=" $ string(self) $ " delta=" $ string(Delta)
            $ " state=" $ string(GetStateName()));
        return;
    }

    if (Role == ROLE_AutonomousProxy)
        VersusMountPredictedAt = Level.TimeSeconds;
    Super.Mount(Delta);
}

function ClientVersusMountBegin(int Serial)
{
    if (!IsLocalViewportPlayer() || Serial <= VersusMountLocalSerial)
        return;
    VersusMountLocalSerial = Serial;
    bVersusMountLocalHold = True;
    bVersusMountReleasePending = False;
    bVersusMountReleaseApplied = False;
    ClearVersusMountPrediction();
    bPressedJump = False;
    bVersusJumpWasDown = bVersusJump;
    Log("HPVersusMount phase=OwnerHold serial=" $ Serial
        $ " role=" $ string(Role) $ " state=" $ string(GetStateName()));
}

function ClientVersusMountEnd(int Serial, vector Position, rotator Facing,
    Actor FinalBase, EPhysics FinalPhysics, float R, float H, float W,
    vector Pivot, float Stamp)
{
    if (!IsLocalViewportPlayer() || Serial != VersusMountLocalSerial)
        return;
    if (bVersusMountReleaseApplied)
    {
        ServerVersusMountResumed(Serial, CurrentTimeStamp);
        return;
    }
    VersusMountReleaseLocation = Position;
    VersusMountReleaseRotation = Facing;
    VersusMountReleaseBase = FinalBase;
    VersusMountReleasePhysics = FinalPhysics;
    VersusMountReleaseRadius = R;
    VersusMountReleaseHeight = H;
    VersusMountReleaseWidth = W;
    VersusMountReleasePivot = Pivot;
    VersusMountReleaseStamp = Stamp;
    bVersusMountReleasePending = True;
    TryApplyVersusMountRelease();
}

function TryApplyVersusMountRelease()
{
    if (!bVersusMountReleasePending || Role != ROLE_AutonomousProxy)
        return;

    ClearVersusMountPrediction();
    if (!IsInState('PlayerWalking'))
        GotoState('PlayerWalking');
    SetCollisionSize(VersusMountReleaseRadius,
        VersusMountReleaseHeight, VersusMountReleaseWidth);
    PrePivot = VersusMountReleasePivot;
    if (!SetLocation(VersusMountReleaseLocation))
    {
        Log("HPVersusMount phase=OwnerRetryPosition serial=" $ VersusMountLocalSerial
            $ " target=" $ string(VersusMountReleaseLocation));
        return;
    }
    SetRotation(VersusMountReleaseRotation);
    SetPhysics(VersusMountReleasePhysics);
    SetBase(VersusMountReleaseBase);
    Velocity = vect(0,0,0);
    Acceleration = vect(0,0,0);
    CurrentTimeStamp = FMax(CurrentTimeStamp, VersusMountReleaseStamp);
    bVersusMountReleasePending = False;
    bVersusMountReleaseApplied = True;
    ServerVersusMountResumed(VersusMountLocalSerial, CurrentTimeStamp);
    Log("HPVersusMount phase=OwnerReleased serial=" $ VersusMountLocalSerial
        $ " location=" $ string(Location) $ " state=" $ string(GetStateName())
        $ " collision=" $ string(CollisionRadius) $ "," $ string(CollisionHeight));
}

function ServerVersusMountResumed(int Serial, float Stamp)
{
    if (Role != ROLE_Authority || !bVersusMountAwaitResume
        || Serial != VersusMountSerial || RemoteRole != ROLE_AutonomousProxy
        || Stamp < VersusMountHoldStamp
        || Stamp > VersusMountHoldStamp
            + (Level.TimeSeconds - VersusMountStartTime) + 5.0)
        return;
    CurrentTimeStamp = FMax(CurrentTimeStamp, Stamp);
    ServerTimeStamp = Level.TimeSeconds;
    TimeMargin = 0.0;
    bVersusMountAwaitResume = False;
    ClientVersusMountCommit(Serial);
    Log("HPVersusMount phase=ServerResumed serial=" $ Serial
        $ " state=" $ string(GetStateName())
        $ " location=" $ string(Location));
}

function ClientVersusMountCommit(int Serial)
{
    if (Serial != VersusMountLocalSerial)
        return;
    ClearVersusMountPrediction();
    bVersusMountLocalHold = False;
    bVersusMountReleasePending = False;
    bVersusJumpWasDown = bVersusJump;
    Log("HPVersusMount phase=OwnerCommitted serial=" $ Serial
        $ " state=" $ string(GetStateName()));
}

function TickVersusMountNetwork()
{
    if (Role != ROLE_Authority)
        return;
    if (bVersusMountNetActive)
    {
        if (bVersusDead)
        {
            CancelVersusMountNetwork();
            return;
        }
        if (IsVersusMountState()
            && Level.TimeSeconds - VersusMountStartTime < 4.0)
            return;
        if (IsVersusMountState())
        {
            Log("HPVersusMount phase=Timeout serial=" $ VersusMountSerial
                $ " state=" $ string(GetStateName()));
            GotoState('PlayerWalking');
            SetCollisionSize(VersusMountOriginalRadius,
                VersusMountOriginalHeight, VersusMountOriginalWidth);
            PrePivot = VersusMountOriginalPivot;
            if (Physics == PHYS_Projectile)
                SetPhysics(PHYS_Falling);
        }
        bVersusMountNetActive = False;
        bVersusMountAwaitResume = True;
        RemoteRole = ROLE_AutonomousProxy;
        VersusMountNextReleaseTime = Level.TimeSeconds + 0.4;
        Log("HPVersusMount phase=RoleRestored serial=" $ VersusMountSerial
            $ " state=" $ string(GetStateName())
            $ " location=" $ string(Location));
        return;
    }
    if (bVersusMountAwaitResume
        && Level.TimeSeconds >= VersusMountNextReleaseTime)
    {
        ClientVersusMountEnd(VersusMountSerial, Location, Rotation,
            Base, Physics, CollisionRadius, CollisionHeight, CollisionWidth,
            PrePivot, CurrentTimeStamp);
        VersusMountNextReleaseTime = Level.TimeSeconds + 1.0;
        Log("HPVersusMount phase=ReleaseSent serial=" $ VersusMountSerial
            $ " location=" $ string(Location));
    }
}

function CancelVersusMountNetwork()
{
    if (Role == ROLE_Authority
        && (bVersusMountNetActive || bVersusMountAwaitResume))
        RemoteRole = ROLE_AutonomousProxy;
    bVersusMountNetActive = False;
    bVersusMountAwaitResume = False;
    bVersusMountLocalHold = False;
    bVersusMountReleasePending = False;
}

function ServerMove(float TimeStamp, vector InAccel, vector ClientLoc,
    bool NewbRun, bool NewbDuck, bool NewbJumpStatus, bool bFired,
    bool bAltFired, bool bForceFire, bool bForceAltFire, eDodgeDir DodgeMove,
    byte ClientRoll, int View, optional byte OldTimeDelta, optional int OldAccel)
{
    // Queued walking packets cannot advance authority while root motion owns
    // the pawn, or before the owner confirms its corrected mount endpoint.
    if (bVersusMountNetActive || bVersusMountAwaitResume)
        return;
    Super.ServerMove(TimeStamp, InAccel, ClientLoc, NewbRun, NewbDuck,
        NewbJumpStatus, bFired, bAltFired, bForceFire, bForceAltFire,
        DodgeMove, ClientRoll, View, OldTimeDelta, OldAccel);
}

function ClientAdjustPosition(float TimeStamp, name NewState, EPhysics NewPhysics,
    float NewLocX, float NewLocY, float NewLocZ,
    float NewVelX, float NewVelY, float NewVelZ, Actor NewBase)
{
    // A generic correction cannot reconstruct Destination/MountDelta or the
    // animation phase. The server's explicit final snapshot restores both.
    if (bVersusMountLocalHold || NewState == 'Mounting'
        || NewState == 'MountFinish')
        return;
    Super.ClientAdjustPosition(TimeStamp, NewState, NewPhysics,
        NewLocX, NewLocY, NewLocZ,
        NewVelX, NewVelY, NewVelZ, NewBase);
}

